#: Celda por defecto del sello de firma electrónica en cada formato ya creado.
SELLO_POR_FORMATO = {
    'SGC-FOR-001': 'A29',
    'SGC-FOR-002': 'A52',
    'SGC-FOR-005': 'A42',
}


def crear_sellos(apps, schema_editor):
    """Agrega el campo ``sello_firma`` a los formatos SGC existentes.

    La firma electrónica se estampa en el XLSX/PDF; sin este campo, las bases
    ya pobladas no mostrarían la evidencia. Es idempotente.
    """
    Formato = apps.get_model('documentos', 'Formato')
    CampoFormato = apps.get_model('documentos', 'CampoFormato')

    for codigo, celda in SELLO_POR_FORMATO.items():
        formato = Formato.objects.filter(codigo=codigo).first()
        if formato is None:
            continue
        if CampoFormato.objects.filter(
            seccion__formato=formato, tipo='sello',
        ).exists():
            continue
        ultimo = CampoFormato.objects.filter(
            seccion__formato=formato,
        ).select_related('seccion').order_by('-seccion__orden', '-orden').first()
        if ultimo is None:
            continue
        CampoFormato.objects.create(
            seccion_id=ultimo.seccion_id,
            clave='sello_firma',
            etiqueta='Sello de firma electrónica',
            tipo='sello',
            origen='sello_firma',
            celda_excel=celda,
            requerido=False,
            orden=99,
        )


def borrar_sellos(apps, schema_editor):
    CampoFormato = apps.get_model('documentos', 'CampoFormato')
    CampoFormato.objects.filter(
        tipo='sello', clave='sello_firma',
    ).delete()


